-- V2-6 P1 (docs/v2-6-poc-adapter-plan): the real realm gets the two PoC
-- templates and nothing else, for phones a host Agent drives with the PoC
-- driver. Both catalogs stay simulation-only for everything else: a real task
-- definition can only be one of the two codes, a real command row only one of
-- the three PoC commands. Existing rows were all 'sim' under the old checks,
-- so the new ones are added NOT VALID (no table scan, no long lock).
ALTER TABLE mx_device.task_definitions DROP CONSTRAINT task_definitions_mode_check;
ALTER TABLE mx_device.task_definitions ADD CONSTRAINT task_definitions_mode_check
 CHECK(mode='sim' OR (mode='real' AND code IN ('xhs.poc.search3','xhs.poc.detail'))) NOT VALID;
ALTER TABLE mx_device.execution_commands DROP CONSTRAINT execution_commands_mode_check;
ALTER TABLE mx_device.execution_commands ADD CONSTRAINT execution_commands_mode_check
 CHECK(mode='sim' OR (mode='real' AND document->>'code' IN ('xhs.search','xhs.search.next','xhs.note.detail'))) NOT VALID;
-- One phone is one real device row: an Agent-hosted phone and a legacy PoC
-- (or observer) registration cannot share an ADB serial. The model refuses it
-- with a reason first; the index holds for every write path.
CREATE UNIQUE INDEX devices_real_serial ON mx_device.devices((document->>'serial')) WHERE mode='real' AND document->>'serial' IS NOT NULL;
